# Copy-FileToAzureBlobContainerWithAzCopy.ps1
# by Ken Hoover <ken.hoover@microsoft.com>
# November 2021

# ==========================
# PREREQUISITES:
#
# The AzCopy utility (azcopy.exe) needs to be in the path or in the same directory as this script. Download azCopy from
# https://docs.microsoft.com/en-us/azure/storage/common/storage-use-azcopy-v10


# ==========================
# REQUIRED PARAMETERS:
#
# CredsFileName :: Name of a file generated by creating a credentials object (with get-credential) that has the storage
#                  account name as the username and the storage account key as the password and then exporting it 
#                  using Export-Clixml.  For an example, see
#                  https://www.jaapbrasser.com/quickly-and-securely-storing-your-credentials-powershell/
#
# targetContainerName :: The name of the blob container in the target storage account to place the file in
#
# fileName :: The name of the file to copy to the blob container


[CmdletBinding()]
param (
    [Parameter(Mandatory=$true)][String]$CredsFileName,
    [Parameter(Mandatory=$true)][String]$targetContainerName,
    [Parameter(Mandatory=$true)][String]$FileName
)

# Read and convert the credentials file into a PSCredential object
# The username should be the storage account name
# the password should be the storage account key
Write-Verbose "Reading storage account credentials from $CredsFileName"
$StorageAccountCredentials = import-clixml -Path $CredsFileName

# Extract the storage account name and the account key from the credentials object
# YOU MUST PROTECT THE KEY. IT IS ROOT FOR THE STORAGE ACCOUNT.
$storageAccountName = $StorageAccountCredentials.UserName
$storageAccountKey = $StorageAccountCredentials.GetNetworkCredential().Password

# Authenticate to the target storage account using the key
Write-Verbose "Authenticating to the target storage account ($StorageAccountName)"
$destinationContext = New-AzStorageContext -StorageAccountName $storageAccountName -StorageAccountKey $storageAccountKey

# Append a timestamp to the file name to avoid overwriting existing files
$timestamp = get-date -format "yyyyMMdd-HHmmss"
$destinationFileName = ((Get-ChildItem $filename).Name)+"-"+$timestamp  # This makes sure that we have just a bare file name
Write-Verbose "Destination file name will be $destinationFileName"

# Create a SAS URI to use to write the target file (valid for 1 day)
Write-Verbose "Creating a SAS URI for the target in container $targetContainerName"
$containerSASURI = New-AzStorageBlobSASToken -Context $destinationContext -ExpiryTime(get-date).AddDays(1) -FullUri -Container $targetContainerName -Blob $destinationFileName -Permission rw

# Copy the file to the target container with AzCopy
Write-Verbose "Copying $fileName to the target as $destinationFileName"
.\azcopy.exe cp $FileName $containerSASURI

